from pathlib import Path
import re,json
root=Path('spartanai-recreation/dist')
rows=[
('cigna-smart-health-systems','upcoding','Upcoding','Kesesuaian diagnosis dan tingkat keparahan','Telaah kesesuaian kode diagnosis, tingkat keparahan, dan tarif klaim dengan bukti pelayanan.','ICD-10','Klinis',[
('Apa yang perlu diperhatikan?','Upcoding adalah indikasi peningkatan kode atau tingkat keparahan yang tidak didukung kondisi pasien. Selisih tarif saja tidak cukup untuk menyimpulkan adanya manipulasi.'),
('Konteks yang ditelaah','Diagnosis ICD-10, kelompok INA CBG, resume medis, tindakan, serta durasi rawat perlu dibaca bersama. Perbedaan kode harus dicocokkan dengan dokumentasi klinis.'),
('Bagaimana SiKePO membantu?','Triage A1 menilai rasio biaya dan durasi rawat. Investigasi A2 membantu memprioritaskan kombinasi fitur yang menyimpang. Temuan kemudian menjadi konteks rekomendasi A3.')],['Cocokkan diagnosis dengan resume medis.','Periksa dasar tingkat keparahan dan tindakan.','Catat alasan koreksi atau kebutuhan dokumen tambahan.']),
('aetna-health-data-ecosystem','phantom-billing','Phantom billing','Bukti pelayanan di balik setiap pengajuan','Telusuri apakah tindakan, obat, atau pemeriksaan yang ditagihkan memiliki bukti pelayanan yang sesuai.','Resume','Bukti',[
('Apa yang perlu diperhatikan?','Phantom billing mengacu pada pengajuan layanan yang diduga tidak pernah diberikan. Ketidaklengkapan dokumen merupakan alasan meminta klarifikasi, bukan bukti otomatis adanya fraud.'),
('Konteks yang ditelaah','Rincian tagihan, catatan tindakan, hasil pemeriksaan, administrasi obat, dan tanggal pelayanan perlu saling cocok. Konfirmasi dilakukan melalui dokumen pendukung yang tersedia.'),
('Bagaimana SiKePO membantu?','SiKePO menyatukan konteks klaim dan temuan pemeriksaan untuk membantu penelusuran. Pembuktian layanan tetap memerlukan dokumen; skor anomali tidak dapat membuktikan tindakan benar-benar dilakukan.')],['Cocokkan item tagihan dengan catatan pelayanan.','Minta bukti tindakan atau hasil pemeriksaan yang belum lengkap.','Dokumentasikan klarifikasi sebelum tindak lanjut.']),
('anthem-neural-care-network','clinical-review','Review klinis','Temuan finansial dibaca bersama konteks klinis','Periksa hubungan diagnosis, durasi rawat, obat, dan biaya sebelum menindaklanjuti suatu sinyal risiko.','INA CBG','Biaya',[
('Apa yang perlu diperhatikan?','Klaim dengan biaya atau durasi rawat tidak biasa dapat memiliki alasan klinis yang sah. Review klinis membantu membedakan kebutuhan pelayanan dari ketidaksesuaian pengajuan.'),
('Konteks yang ditelaah','SiKePO memakai diagnosis, acuan durasi rawat, rasio biaya, jumlah obat, dan obat restriksi sebagai bagian dari konteks penilaian. Resume medis dibutuhkan untuk menjelaskan temuan.'),
('Bagaimana SiKePO membantu?','A1 memeriksa aturan awal dan A2 menelaah tujuh fitur numerik. Fusi skor membantu menyusun prioritas. Ringkasan A3 menyediakan alasan rekomendasi untuk ditelaah kembali.')],['Telaah alasan durasi perawatan.','Cocokkan obat restriksi dengan dokumentasi indikasi.','Bandingkan selisih biaya dengan rincian pelayanan.']),
('cvs-smart-supply-chain-hub','inflated-bills','Inflated bills','Menelaah selisih pengajuan dan tarif','Kenali pengajuan biaya yang perlu dijelaskan melalui rincian pelayanan dan tarif acuan.','Tarif','Klaim',[
('Apa yang perlu diperhatikan?','Pembengkakan tagihan ditelaah melalui perbandingan biaya pengajuan, tarif acuan, dan rincian pelayanan. Sinyal finansial harus dibaca sesuai konteks berkas dan ketentuan yang berlaku.'),
('Konteks yang ditelaah','Rasio biaya terhadap tarif INA CBG dan proporsi selisih biaya menjadi bagian dari fitur investigasi. Durasi rawat serta penggunaan obat membantu memberi konteks tambahan.'),
('Bagaimana SiKePO membantu?','Triage berbasis aturan mengidentifikasi rasio yang perlu perhatian. IsolationForest menilai kombinasi fitur. Hasil keduanya dipadukan agar review dapat difokuskan pada klaim yang paling perlu ditelusuri.')],['Bandingkan pengajuan dengan tarif acuan.','Telusuri komponen yang menghasilkan selisih.','Minta penjelasan dan dokumen untuk komponen yang belum jelas.']),
('united-ai-security-protocol','duplicate-claims','Duplikasi klaim','Satu pelayanan, jejak pengajuan yang jelas','Telusuri pengajuan dengan identitas atau rincian mirip untuk membedakan duplikasi dari koreksi berkas yang sah.','ID klaim','Berkas',[
('Apa yang perlu diperhatikan?','Duplikasi adalah pengajuan berulang yang perlu ditelaah hubungan antarberkasnya. Pengajuan ulang dapat juga merupakan koreksi atau proses administratif yang sah.'),
('Konteks yang ditelaah','Bandingkan ID klaim, fasilitas kesehatan, identitas pasien yang berwenang diakses, tanggal masuk dan keluar, diagnosis, serta rincian biaya. Riwayat berkas diperlukan agar hubungan pengajuan dapat dipahami.'),
('Bagaimana SiKePO membantu?','Duplikasi merupakan salah satu fokus investigasi dalam handover SiKePO. Pencocokan lintas berkas membutuhkan riwayat data; halaman ini menjelaskan konsep dan tidak menunjukkan bahwa backend pencocokan sudah dijalankan.')],['Bandingkan identitas dan tanggal pelayanan antarberkas.','Periksa hubungan pengajuan awal dengan koreksi.','Catat hasil konfirmasi sebelum menentukan tindak lanjut.'])]
fonts='\n'.join(b for b in re.findall(r'@font-face\s*\{[^}]*\}',(root/'index.html').read_text(encoding='utf-8')) if ('font-family: "Inter";' in b or 'font-family: "Inter Display";' in b or "font-family: 'Geist Mono'" in b) and ('font-weight: 400' in b or 'font-weight: 500' in b))
