css='''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:#1a1a1a;font-family:Inter,sans-serif;font-size:16px;line-height:1.5}a{color:inherit;text-decoration:none}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:"Inter Display",Inter,sans-serif;font-weight:500;letter-spacing:-.04em}nav{position:absolute;inset:28px 32px auto;display:flex;justify-content:space-between;z-index:5}.nav-links{display:flex;align-items:center;gap:28px;padding:8px 24px 8px 12px;background:#ffffffed;border-radius:50px;font-size:14px;backdrop-filter:blur(16px)}.nav-links img{width:36px;height:36px;object-fit:contain}.dashboard{display:flex;align-items:center;gap:12px;background:#fff;border-radius:12px;padding:4px 16px 4px 4px;font-size:14px}.dashboard span{background:#206b4a;color:#fff;border-radius:10px;padding:8px 12px;font-size:20px}.hero{margin:12px;border-radius:24px;overflow:hidden;height:70vh;min-height:440px;max-height:800px;background:#183124}.hero img{width:100%;height:100%;object-fit:cover}main{max-width:1440px;margin:auto;padding:64px 40px}.breadcrumb{font-size:12px;color:#858585;margin-bottom:32px}.breadcrumb a:hover{text-decoration:underline}.intro{display:grid;grid-template-columns:1.3fr 1fr;gap:64px;margin-bottom:64px}h1{font-size:70px;line-height:1.1;margin-bottom:24px}.lede{max-width:680px;color:#777;font-size:20px;line-height:1.5}.metadata{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-content:start;padding-top:12px}.metadata small{display:block;font-size:12px;color:#909090;margin-bottom:8px}.metadata strong{font-size:16px;font-weight:400}.signals{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:80px}.signal{background:#f0f0ee;border-radius:16px;padding:24px}.signal b{display:block;font-family:"Inter Display",sans-serif;font-size:30px;font-weight:400;letter-spacing:-1px;margin-bottom:12px}.signal small{color:#888;font-size:12px}.statement{font-size:48px;line-height:1.1;max-width:960px;margin:0 0 64px}.content{display:grid;grid-template-columns:260px 1fr;gap:64px}.aside{font-size:12px;letter-spacing:.08em;color:#888}.body-copy{max-width:800px}.body-copy section{margin-bottom:48px}.body-copy h2{font-size:30px;line-height:1.2;margin-bottom:16px}.body-copy p{color:#707070;line-height:1.75}.wide-image{margin:64px 0;border-radius:20px;overflow:hidden}.wide-image img{display:block;width:100%;max-height:560px;object-fit:cover}.review{display:grid;grid-template-columns:1fr 1fr;gap:64px;padding:48px;background:#1a1a1a;color:white;border-radius:20px}.review h2{font-size:36px;line-height:1.1}.review ol{padding-left:24px;color:#ccc}.review li{padding-left:8px;margin-bottom:16px}.notice{font-size:12px;color:#888;margin-top:24px;max-width:780px}.related{margin-top:96px}.related h2{font-size:48px;line-height:1.1;margin-bottom:32px}.related-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.related a{background:#f2f2f0;border-radius:16px;overflow:hidden}.related img{display:block;width:100%;aspect-ratio:1.65;object-fit:cover}.related span{display:flex;justify-content:space-between;padding:16px;font-size:14px}.related a:hover{color:#206b4a}.footer{display:flex;align-items:center;justify-content:space-between;gap:24px;background:#1a1a1a;color:white;padding:40px;margin-top:64px}.footer img{width:40px;height:40px}.footer div{display:flex;align-items:center;gap:16px}.footer p{font-size:12px;color:#aaa}a:focus-visible{outline:2px solid #206b4a;outline-offset:4px}.skip{position:absolute;top:-100px;background:#fff;padding:12px;z-index:10}.skip:focus{top:12px}@media(max-width:1000px){.intro{gap:32px}h1{font-size:56px}.signals{grid-template-columns:1fr 1fr}.content{grid-template-columns:180px 1fr;gap:32px}.related-grid{grid-template-columns:1fr 1fr}.nav-links{gap:16px}}@media(max-width:700px){nav{inset:24px 24px auto}.nav-links{gap:12px;padding:8px 12px}.nav-links a:not(.home){display:none}.dashboard{font-size:12px}.hero{height:420px;min-height:0;margin:8px;border-radius:20px}.hero img{object-position:center}main{padding:40px 24px}.intro,.content,.review{grid-template-columns:1fr;gap:32px}h1{font-size:45px}.lede{font-size:18px}.metadata{gap:24px}.signals{margin-bottom:48px}.signal{padding:16px}.signal b{font-size:24px}.statement{font-size:36px;margin-bottom:48px}.review{padding:24px}.review h2{font-size:30px}.related{margin-top:64px}.related h2{font-size:36px}.related-grid{gap:12px}.related span{padding:12px;font-size:12px}.footer{padding:24px;align-items:start;flex-direction:column}.wide-image{margin:40px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''
(root/'project'/'detail.css').write_text(fonts+'\n'+css,encoding='utf-8')
for slug,image,title,subtitle,lede,reference,focus,sections,checks in rows:
 related=''.join(f'<a href="/project/{r[0]}/"><img src="/assets/sikepo-card-{r[1]}.png" alt="Ilustrasi {r[2]}"><span>{r[2]} <b aria-hidden="true">↗</b></span></a>' for r in rows if r[0]!=slug)
 body=''.join(f'<section><h2>{h}</h2><p>{p}</p></section>' for h,p in sections)
 page=f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SIKEPO</title><meta name="description" content="{lede}"><link rel="icon" href="/assets/sikepo-symbol-black.png" media="(prefers-color-scheme:light)"><link rel="icon" href="/assets/sikepo-symbol-white.png" media="(prefers-color-scheme:dark)"><link rel="stylesheet" href="/project/detail.css?v=1"></head><body><a class="skip" href="#main">Lewati ke konten</a><nav aria-label="Navigasi utama"><div class="nav-links"><a class="home" href="/" aria-label="SIKEPO, beranda"><img src="/assets/sikepo-symbol-black.png" alt="SIKEPO"></a><a href="/#fokus-risiko">Fokus risiko</a><a href="/#capabilities">Kapabilitas</a><a href="/#pipeline">Pipeline</a><a href="/#pricing">Peran</a></div><a class="dashboard" href="/dashboard/"><span aria-hidden="true">↗</span>Dashboard</a></nav><div class="hero"><img src="/assets/sikepo-card-{image}.png" alt="Visual SIKEPO untuk {title}"></div><main id="main"><div class="breadcrumb"><a href="/">Beranda</a> / <a href="/#fokus-risiko">Fokus risiko</a> / {title}</div><div class="intro"><div><h1>{title}</h1><p class="lede">{lede}</p></div><div class="metadata"><div><small>Konteks</small><strong>Audit klaim BPJS/JKN</strong></div><div><small>Acuan data</small><strong>{reference}</strong></div><div><small>Fokus pemeriksaan</small><strong>{focus}</strong></div><div><small>Workspace</small><a href="/dashboard/">Buka dashboard ↗</a></div></div></div><div class="signals"><div class="signal"><b>A1</b><small>Triage aturan</small></div><div class="signal"><b>A2</b><small>Investigasi anomali</small></div><div class="signal"><b>A3</b><small>Rekomendasi adjudikasi</small></div><div class="signal"><b>Review</b><small>Penelusuran oleh pengguna</small></div></div><h2 class="statement">{subtitle}.</h2><div class="content"><div class="aside">FOKUS INVESTIGASI / SIKEPO</div><div class="body-copy">{body}</div></div><figure class="wide-image"><img src="/assets/sikepo-card-{image}.png" alt="Ilustrasi konsep {title}" loading="lazy"></figure><section class="review"><h2>Dari sinyal risiko<br>ke penelusuran berkas.</h2><ol>{''.join('<li>'+x+'</li>' for x in checks)}</ol></section><p class="notice">Halaman ini merupakan penjelasan konsep berdasarkan handover SiKePO. Visual bersifat ilustratif. Sinyal risiko bukan bukti fraud; penetapan tindak lanjut memerlukan pemeriksaan dokumen dan kewenangan pengguna.</p><section class="related"><h2>Fokus lainnya.</h2><div class="related-grid">{related}</div></section></main><footer class="footer"><div><img src="/assets/sikepo-symbol-white.png" alt=""><strong>SIKEPO</strong></div><p>Sistem Investigasi Kelayakan Klaim & Pola Overbilling</p><a href="/#fokus-risiko">Kembali ke fokus risiko ↗</a></footer></body></html>'''
 dest=root/'project'/slug;dest.mkdir(exist_ok=True);(dest/'index.html').write_text(page,encoding='utf-8')
print('Created 5 local detail pages')
